CORPUS = ["main ghar ja raha hoon", "main school ja raha hoon", "tum ghar ja rahe ho"]
def bigram_prob(sentences, w1, w2):
    all_words = []
    bigrams = []
    for s in sentences:
        words = ["<s>"] + s.lower().split() + ["</s>"]
        for i in range(len(words)):
            all_words.append(words[i])
        for i in range(len(words) - 1):
            bigrams.append((words[i], words[i+1]))
    vocab = []
    for w in all_words:
        if w not in vocab:
            vocab.append(w)
    V = len(vocab)
    count_w1 = 0
    count_w1w2 = 0
    for i in range(len(bigrams)):
        if bigrams[i][0] == w1:
            count_w1 = count_w1 + 1
            if bigrams[i][1] == w2:
                count_w1w2 = count_w1w2 + 1
    prob = (count_w1w2 + 1) / (count_w1 + V)
    return round(prob, 4)
def sentence_prob(sentences, sentence):
    words = ["<s>"] + sentence.lower().split() + ["</s>"]
    total_p = 1.0
    for i in range(len(words) - 1):
        p = bigram_prob(sentences, words[i], words[i+1])
        total_p = total_p * p
    return round(total_p, 6)
print(bigram_prob(CORPUS, "ja", "raha"))

